#!/usr/bin/env bun

type Task = { id: string; duration: number; dependsOn: string[] };
type Plan = {
  order: string[];
  layers: string[][];
  earliest: Record<string, { start: number; finish: number }>;
  totalDuration: number;
  criticalPath: string[];
};

function fail(message: string): never {
  throw new Error(message);
}

function validate(input: unknown): Task[] {
  if (input === null || typeof input !== "object" || Array.isArray(input)) {
    fail("Input must be an object with a tasks array.");
  }
  const record = input as Record<string, unknown>;
  if (!Array.isArray(record.tasks)) fail("tasks must be an array.");

  const ids = new Set<string>();
  const tasks: Task[] = record.tasks.map((value, index) => {
    if (value === null || typeof value !== "object" || Array.isArray(value)) {
      fail(`tasks[${index}] must be an object.`);
    }
    const task = value as Record<string, unknown>;
    if (typeof task.id !== "string" || task.id.length === 0) {
      fail(`tasks[${index}].id must be a non-empty string.`);
    }
    if (ids.has(task.id)) fail(`Duplicate task id: ${task.id}`);
    ids.add(task.id);
    if (typeof task.duration !== "number" || !Number.isFinite(task.duration) || task.duration < 0) {
      fail(`tasks[${index}].duration must be a finite non-negative number.`);
    }
    const dependencies = task.dependsOn === undefined ? [] : task.dependsOn;
    if (!Array.isArray(dependencies) || !dependencies.every((id) => typeof id === "string")) {
      fail(`tasks[${index}].dependsOn must be an array of strings.`);
    }
    if (new Set(dependencies).size !== dependencies.length) {
      fail(`tasks[${index}].dependsOn must contain unique ids.`);
    }
    if (dependencies.includes(task.id)) fail(`Task ${task.id} cannot depend on itself.`);
    return { id: task.id, duration: task.duration, dependsOn: dependencies as string[] };
  });

  for (const task of tasks) {
    for (const dependency of task.dependsOn) {
      if (!ids.has(dependency)) fail(`Task ${task.id} depends on unknown task: ${dependency}`);
    }
  }
  return tasks;
}

function findCycle(tasks: Task[], byId: Map<string, Task>): string[] | undefined {
  const state = new Map<string, 0 | 1 | 2>();
  const stack: string[] = [];
  const visit = (id: string): string[] | undefined => {
    state.set(id, 1);
    stack.push(id);
    for (const dep of [...byId.get(id)!.dependsOn].sort()) {
      if (state.get(dep) === 1) return [...stack.slice(stack.indexOf(dep)), dep];
      if (state.get(dep) !== 2) {
        const cycle = visit(dep);
        if (cycle) return cycle;
      }
    }
    stack.pop();
    state.set(id, 2);
  };
  for (const task of [...tasks].sort((a, b) => a.id.localeCompare(b.id))) {
    if (!state.has(task.id)) {
      const cycle = visit(task.id);
      if (cycle) return cycle;
    }
  }
}

export function createPlan(tasks: Task[]): Plan {
  const byId = new Map(tasks.map((task) => [task.id, task]));
  const cycle = findCycle(tasks, byId);
  if (cycle) fail(`Cycle detected: ${cycle.join(" -> ")}`);

  const dependents = new Map(tasks.map((task) => [task.id, [] as string[]]));
  const remaining = new Map(tasks.map((task) => [task.id, task.dependsOn.length]));
  for (const task of tasks) for (const dep of task.dependsOn) dependents.get(dep)!.push(task.id);

  const ready = tasks.filter((task) => task.dependsOn.length === 0).map((task) => task.id).sort();
  const order: string[] = [];
  while (ready.length) {
    const id = ready.shift()!;
    order.push(id);
    for (const child of dependents.get(id)!.sort()) {
      const count = remaining.get(child)! - 1;
      remaining.set(child, count);
      if (count === 0) {
        ready.push(child);
        ready.sort();
      }
    }
  }

  const earliest: Plan["earliest"] = {};
  const layers: string[][] = [];
  const paths = new Map<string, string[]>();
  let totalDuration = 0;
  let criticalPath: string[] = [];
  for (const id of order) {
    const task = byId.get(id)!;
    let start = 0;
    let layer = 0;
    let predecessor: string | undefined;
    for (const dep of task.dependsOn) {
      const finish = earliest[dep].finish;
      if (finish > start || (finish === start && (predecessor === undefined || comparePaths(paths.get(dep)!, paths.get(predecessor)!) < 0))) {
        start = finish;
        predecessor = dep;
      }
      layer = Math.max(layer, layerOf(dep, layers) + 1);
    }
    const finish = start + task.duration;
    earliest[id] = { start, finish };
    while (layers.length <= layer) layers.push([]);
    layers[layer].push(id);
    paths.set(id, predecessor ? [...paths.get(predecessor)!, id] : [id]);
    const path = paths.get(id)!;
    if (finish > totalDuration || (finish === totalDuration && comparePaths(path, criticalPath) < 0)) {
      totalDuration = finish;
      criticalPath = path;
    }
  }
  for (const layer of layers) layer.sort();
  return { order, layers, earliest, totalDuration, criticalPath };
}

function layerOf(id: string, layers: string[][]): number {
  for (let index = 0; index < layers.length; index++) if (layers[index].includes(id)) return index;
  return -1;
}

function comparePaths(a: string[], b: string[]): number {
  for (let index = 0; index < Math.min(a.length, b.length); index++) {
    const comparison = a[index].localeCompare(b[index]);
    if (comparison) return comparison;
  }
  return a.length - b.length;
}

async function main(): Promise<void> {
  const [command, inputFile, ...extra] = Bun.argv.slice(2);
  if (command !== "plan" || !inputFile || extra.length) {
    fail("Usage: bun run src/cli.ts plan INPUT.json");
  }
  let raw: string;
  try { raw = await Bun.file(inputFile).text(); } catch { fail(`Cannot read input file: ${inputFile}`); }
  let input: unknown;
  try { input = JSON.parse(raw); } catch { fail("Invalid JSON input."); }
  console.log(JSON.stringify(createPlan(validate(input))));
}

if (import.meta.main) {
  main().catch((error: unknown) => {
    console.error(error instanceof Error ? error.message : String(error));
    process.exit(1);
  });
}
import { describe, expect, test } from "bun:test";
import { createPlan } from "./cli";

describe("dependency planner", () => {
  test("plans deterministic layers, times, and critical path", () => {
    expect(createPlan([
      { id: "deploy", duration: 1, dependsOn: ["build"] },
      { id: "lint", duration: 2, dependsOn: [] },
      { id: "build", duration: 3, dependsOn: ["lint"] },
      { id: "docs", duration: 6, dependsOn: [] },
    ])).toEqual({
      order: ["docs", "lint", "build", "deploy"],
      layers: [["docs", "lint"], ["build"], ["deploy"]],
      earliest: { docs: { start: 0, finish: 6 }, lint: { start: 0, finish: 2 }, build: { start: 2, finish: 5 }, deploy: { start: 5, finish: 6 } },
      totalDuration: 6,
      criticalPath: ["docs"],
    });
  });

  test("chooses lexicographically smallest equal critical path", () => {
    expect(createPlan([
      { id: "z", duration: 1, dependsOn: ["b", "a"] },
      { id: "b", duration: 1, dependsOn: [] },
      { id: "a", duration: 1, dependsOn: [] },
